import csv, pathlib, re, sqlite3, json
p=pathlib.Path(__file__).parent
read=lambda name:list(csv.DictReader(open(p/name,newline='')))
sources=read('sources.csv'); claims=read('claims.csv'); edges=read('edges.csv')
issues=[]
for s in sources:
 if not re.fullmatch(r'\d{4}-\d{2}-\d{2}|\d{4}',s['source_date']):issues.append(('BAD_DATE',s['id'],s['source_date']))
 if not s['url'].startswith('https://'):issues.append(('BAD_URL',s['id'],s['url']))
 if s['kind'].startswith('https://'):issues.append(('SHIFTED_COLUMNS',s['id'],s['kind']))
for c in claims:
 if c['source_id'] and c['source_id'] not in {s['id'] for s in sources}:issues.append(('MISSING_SOURCE',c['id'],c['source_id']))
for e in edges:
 if e['claim_id'] not in {c['id'] for c in claims}:issues.append(('MISSING_CLAIM',e['claim_id'],''))
print(json.dumps({'sources':len(sources),'claims':len(claims),'edges':len(edges),'issues':issues},indent=2))
