bash -lc cat > /mnt/data/gmri_investigation/threat_logic.py <<'PY'
#!/usr/bin/env python3
"""GMRI deterministic discovery/triage engine. No LLM claims of verification."""
import argparse, csv, hashlib, json, re, sqlite3, urllib.request, xml.etree.ElementTree as ET
from datetime import datetime, timezone
from pathlib import Path
from urllib.parse import urlsplit

ROOT=Path(__file__).resolve().parent
SOURCES={
 'cisa_alerts':('government','https://www.cisa.gov/cybersecurity-advisories/all.xml'),
 'bleepingcomputer':('specialist','https://www.bleepingcomputer.com/feed/'),
 'hackernews':('community','https://hnrss.org/newest?q=cyberattack'),
 'reddit_netsec':('community','https://www.reddit.com/r/netsec/.rss'),
 'reddit_sysadmin':('community','https://www.reddit.com/r/sysadmin/.rss'),
 'reddit_worldnews':('community','https://www.reddit.com/r/worldnews/.rss'),
 'github_security':('technical','https://github.com/advisories.atom'),
 'krebs':('specialist','https://krebsonsecurity.com/feed/'),
 'therecord':('specialist','https://therecord.media/feed'),
}
# Sources without dependable public feeds are explicitly tracked as discovery gaps.
MANUAL_CHANNELS=['X','Bluesky','Mastodon','Telegram','Discord','Facebook local groups','local news','YouTube','independent journalist newsletters']
TERMS={
 'cyber_physical':r'cooling|refrigerat|freezer|industrial control|scada|plc|water treatment|power grid|substation|hospital|medical device|food supply',
 'state_cyber':r'north korea|dprk|russia|iran|china|state.sponsored|apt\b|military|pentagon|defense',
 'financial':r'crypto|bank|swift|exchange|billion|launder|sanction|ransomware|funds stolen',
 'governance':r'election|regulat|oversight|corrupt|cover.up|whistleblow|court|congress',
 'ai':r'artificial intelligence|\bai\b|autonomous|agentic|model deployment|data center',
}
IMPACT=[(r'killed|fatalit|death|patient|hospital|ambulance',5),(r'power grid|water treatment|food supply|refrigerat|freezer|military|pentagon',4),(r'billion|ransomware|election|state.sponsored',3)]

def canonical(s):
 s=re.sub(r'https?://','',s.lower());s=re.sub(r'[^a-z0-9 ]',' ',s)
 return ' '.join(w for w in s.split() if w not in {'the','a','an','of','in','on','and','to','for','with'})

def init(db):
 db.executescript('''CREATE TABLE IF NOT EXISTS discoveries (id TEXT PRIMARY KEY,source TEXT,source_class TEXT,title TEXT,url TEXT,published TEXT,first_seen TEXT,domains TEXT,impact INTEGER,urgency INTEGER,status TEXT,raw_hash TEXT);
 CREATE TABLE IF NOT EXISTS observations (id TEXT PRIMARY KEY, discovery_id TEXT, note TEXT, evidence_state TEXT, source_url TEXT);
 CREATE TABLE IF NOT EXISTS links (a TEXT,b TEXT,relation TEXT,evidence_state TEXT,shared_terms TEXT,PRIMARY KEY(a,b,relation));
 CREATE TABLE IF NOT EXISTS runs (run_id TEXT PRIMARY KEY,started TEXT,feeds_ok INTEGER,feeds_failed INTEGER,items_seen INTEGER,items_new INTEGER,errors TEXT);''')

def parse_feed(blob):
 root=ET.fromstring(blob);out=[]
 for e in root.findall('.//item'):
  def t(k):return (e.findtext(k) or '').strip()
  out.append((t('title'),t('link'),t('pubDate')))
 for e in root.findall('{http://www.w3.org/2005/Atom}entry'):
  link=e.find('{http://www.w3.org/2005/Atom}link')
  out.append(((e.findtext('{http://www.w3.org/2005/Atom}title') or '').strip(),link.get('href','') if link is not None else '',e.findtext('{http://www.w3.org/2005/Atom}updated') or ''))
 return [x for x in out if x[0] and x[1]]

def score(title):
 domains=[k for k,p in TERMS.items() if re.search(p,title,re.I)]
 impact=max((n for p,n in IMPACT if re.search(p,title,re.I)),default=1)
 urgency=min(10,impact+min(3,len(domains))+int('cyber_physical' in domains))
 return domains,impact,urgency

def ingest(db,source,klass,title,url,published,now):
 # Preserve source URL and first-seen; do not treat the title as verified evidence.
 ident=hashlib.sha256((source+'|'+url).encode()).hexdigest()[:20]
 domains,impact,urgency=score(title)
 raw_hash=hashlib.sha256((title+'|'+url+'|'+published).encode()).hexdigest()
 cur=db.execute('INSERT OR IGNORE INTO discoveries VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',(ident,source,klass,title,url,published,now,','.join(domains),impact,urgency,'UNVERIFIED_LEAD',raw_hash))
 return cur.rowcount

def correlate(db):
 # Suggest candidate relationships only. Shared category is NEVER proof of a shared actor.
 rows=db.execute('SELECT id,title,domains FROM discoveries').fetchall()
 for i,(a,ta,da) in enumerate(rows):
  wa=set(canonical(ta).split());ca=set(da.split(','))-set([''])
  for b,tb,dbs in rows[i+1:]:
   wb=set(canonical(tb).split());cb=set(dbs.split(','))-set([''])
   overlap=wa&wb
   if len(overlap)>=3 and ca&cb:
    db.execute('INSERT OR IGNORE INTO links VALUES (?,?,?,?,?)',(a,b,'candidate_overlap','UNVERIFIED',','.join(sorted(overlap))))

def main():
 p=argparse.ArgumentParser();p.add_argument('--fixture',help='JSON list of source/title/url/published');p.add_argument('--live',action='store_true');p.add_argument('--db',default=str(ROOT/'threat_discovery.sqlite'));a=p.parse_args()
 db=sqlite3.connect(a.db);init(db);now=datetime.now(timezone.utc).isoformat();ok=fail=seen=new=0;errors=[]
 if a.fixture:
  for x in json.loads(Path(a.fixture).read_text()):
   seen+=1;new+=ingest(db,x['source'],x.get('source_class','unknown'),x['title'],x['url'],x.get('published',''),now)
  ok=1
 if a.live:
  for name,(klass,url) in SOURCES.items():
   try:
    req=urllib.request.Request(url,headers={'User-Agent':'GMRI-Research/1.0 (public feed reader)'})
    with urllib.request.urlopen(req,timeout=8) as response: items=parse_feed(response.read(2_000_000))
    ok+=1
    for title,link,published in items[:100]:
     seen+=1;new+=ingest(db,name,klass,title,link,published,now)
   except Exception as ex:
    fail+=1;errors.append({'source':name,'error':str(ex)[:180]})
 correlate(db);db.execute('INSERT INTO runs VALUES (?,?,?,?,?,?,?)',(hashlib.sha256(now.encode()).hexdigest()[:12],now,ok,fail,seen,new,json.dumps(errors)));db.commit()
 print(json.dumps({'feeds_ok':ok,'feeds_failed':fail,'items_seen':seen,'new_leads':new,'candidate_links':db.execute('SELECT count(*) FROM links').fetchone()[0],'errors':errors,'manual_channels_not_automatically_collected':MANUAL_CHANNELS},indent=2))
 for row in db.execute('SELECT title,urgency,source,status FROM discoveries ORDER BY urgency DESC LIMIT 12'):print('PRIORITY',row)
if __name__=='__main__':main()
